def main():
    H, W, K = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Function to check if a cell is valid
    def is_valid(i, j):
        return 0 <= i < H and 0 <= j < W and grid[i][j] == '.'

    # Initialize a 3D DP array: dp[step][i][j] = number of ways to reach (i,j) in 'step' steps
    # Since K is up to 11, and H, W up to 10, this is manageable
    dp = [[[0 for _ in range(W)] for _ in range(H)] for _ in range(K+1)]

    # Initialize for step 0: starting at each empty cell
    for i in range(H):
        for j in range(W):
            if is_valid(i, j):
                dp[0][i][j] = 1

    # Fill the DP table
    for step in range(K):
        for i in range(H):
            for j in range(W):
                if dp[step][i][j] == 0:
                    continue
                for dx, dy in directions:
                    ni, nj = i + dx, j + dy
                    if is_valid(ni, nj):
                        dp[step + 1][ni][nj] += dp[step][i][j]

    # Sum all ways to reach any cell in K steps
    result = sum(sum(row) for row in dp[K])
    print(result)

