    # Mapping from T to S (for checking consistency)
    t_to_s = {}

    for s, t in zip(S, T):
        if s == t:
            continue
        if s in s_to_t:
            if s_to_t[s] != t:
                print(-1)
                return
        else:
            s_to_t[s] = t
        if t in t_to_s:
            if t_to_s[t] != s:
                print(-1)
                return
        else:
            t_to_s[t] = s

    # Now, we need to find the minimum number of operations
    # Each operation is a replacement of a character in S to another
    # We can model this as a graph where each node is a character, and edges represent replacements
    # We need to find the minimum number of steps to transform S to T

    # We can use BFS to find the minimum number of operations
    from collections import deque

    # Build the graph
    graph = {}
    for s, t in zip(S, T):
        if s != t:
            if s not in graph:
                graph[s] = set()
            if t not in graph:
                graph[t] = set()
            graph[s].add(t)
            graph[t].add(s)

    # BFS to find the minimum number of operations
    visited = set()
    queue = deque()
    for char in set(S):
        if char not in graph:
            queue.append((char, 0))

    min_ops = float('inf')
    while queue:
        current, ops = queue.popleft()
        if current in visited:
            continue
        visited.add(current)
        if current in graph:
            for neighbor in graph[current]:
                if neighbor not in visited:
                    queue.append((neighbor, ops + 1))
        if current in s_to_t:
            if s_to_t[current] == T[S.index(current)]:
                min_ops = min(min_ops, ops + 1)

    print(min_ops if min_ops != float('inf') else -1)

