from collections import defaultdict, deque

def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    M = int(data[1])

    edges = []
    for i in range(M):
        u = int(data[2 + 2*i])
        v = int(data[2 + 2*i + 1])
        edges.append((u, v))

    # Build adjacency list
    adj = [[] for _ in range(N+1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Build bipartition
    color = [-1] * (N+1)
    is_bipartite = True
    for start in range(1, N+1):
        if color[start] == -1:
            queue = deque()
            queue.append(start)
            color[start] = 0
            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = color[u] ^ 1
                        queue.append(v)
                    elif color[v] == color[u]:
                        is_bipartite = False
    if not is_bipartite:
        print("Aoki")
        return

    # Count the number of vertices in each partition
    part0 = 0
    part1 = 0
    for i in range(1, N+1):
        if color[i] == 0:
            part0 += 1
        else:
            part1 += 1

    # The number of edges that can be added without creating an odd cycle is
    # part0 * part1
    total = part0 * part1

    # If total is zero, the first player loses (Aoki wins)
    if total == 0:
        print("Aoki")
    else:
        # If total is odd, the first player wins (Aoki)
        # If total is even, the second player wins (Takahashi)
        if total % 2 == 1:
            print("Aoki")
        else:
            print("Takahashi")

