def main():
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:]))

    # For each position K, find the maximum size Takahashi can have
    result = [0] * N

    # We'll use a stack-based approach to find the maximum possible size
    # for each position
    stack = []
    for i in range(N):
        # While the top of the stack is smaller than current A[i], we can absorb it
        while stack and stack[-1] < A[i]:
            stack[-1] += A[i]
            # After absorbing, the next element can be considered
            # We need to check again
        if not stack or stack[-1] < A[i]:
            stack.append(A[i])
        else:
            # If the top is larger, we can't absorb it, so we keep it
            pass

    # Now, for each position, we need to find the maximum size
    # that can be achieved by absorbing to the left and right
    # We'll use a different approach here

    # We'll use a dynamic programming approach
    # Let's create two arrays: left and right
    # left[i] is the maximum size Takahashi can have if he starts at position i and absorbs to the left
    # right[i] is the maximum size if he starts at position i and absorbs to the right

    left = [0] * N
    right = [0] * N

    # Compute left[i]
    for i in range(N):
        if i == 0:
            left[i] = A[i]
        else:
            if A[i] > A[i-1]:
                left[i] = left[i-1] + A[i]
            else:
                left[i] = A[i]

    # Compute right[i]
    for i in range(N-1, -1, -1):
        if i == N-1:
            right[i] = A[i]
        else:
            if A[i] > A[i+1]:
                right[i] = right[i+1] + A[i]
            else:
                right[i] = A[i]

    # Now, for each position K, the maximum size is the maximum between left[K] and right[K]
    for i in range(N):
        result[i] = max(left[i], right[i])

    print(' '.join(map(str, result)))

